package cmd

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"text/template"
)

const opencodePluginTemplate = `// auxly-capture.js — OpenCode session capture plugin for Auxly Memory
// Automatically generated by 'auxly hooks install --agent opencode'. Do not edit.

import child_process from "node:child_process";

const lastCaptured = new Map();

export const AuxlyCapture = async ({ client }) => ({
  event: async ({ event }) => {
    try {
      const eventType = event?.type;
      const isIdle = eventType === "session.idle" ||
        (eventType === "session.status" && event?.properties?.status?.type === "idle");
      if (!isIdle) {
        return;
      }

      const sessionID = event?.properties?.sessionID;
      if (!sessionID) {
        return;
      }

      const now = Date.now();
      const last = lastCaptured.get(sessionID);
      if (last && (now - last) < 60000) {
        return;
      }
      // Set before the await so idle + status events fired together can't both
      // pass; cleared again if the fetch fails so the next idle can retry.
      lastCaptured.set(sessionID, now);

      let res;
      try {
        res = await client.session.messages({ path: { id: sessionID } });
      } catch {
        lastCaptured.delete(sessionID);
        return;
      }

      const messages = Array.isArray(res) ? res : (res?.data || []);
      if (!Array.isArray(messages) || messages.length === 0) {
        lastCaptured.delete(sessionID);
        return;
      }

      let transcript = "";
      for (const msg of messages) {
        const role = msg?.info?.role || msg?.role || "user";
        const parts = msg?.parts;
        if (!Array.isArray(parts)) {
          continue;
        }
        const textParts = [];
        for (const part of parts) {
          if (part?.type === "text" && typeof part.text === "string") {
            const trimmed = part.text.trim();
            if (trimmed) {
              textParts.push(trimmed);
            }
          }
        }
        if (textParts.length > 0) {
          transcript += role + ": " + textParts.join("\n") + "\n";
        }
      }

      if (transcript.length < 8000) {
        return;
      }

      const auxlyPath = {{ .AuxlyPath }};
      const child = child_process.spawn(auxlyPath, ["capture", "--provider", "opencode"], {
        detached: true,
        stdio: ["pipe", "ignore", "ignore"]
      });
      child.on("error", () => {});
      if (child.stdin) {
        child.stdin.on("error", () => {});
        child.stdin.write(transcript);
        child.stdin.end();
      }
      child.unref();
    } catch {
      // Must never throw or block opencode
    }
  }
});
`

// opencodePluginPath returns ~/.config/opencode/plugins/auxly-capture.js for a given home dir.
func opencodePluginPath(home string) string {
	return filepath.Join(home, ".config", "opencode", "plugins", "auxly-capture.js")
}

// defaultOpencodePluginPath resolves the plugin path using the current user's home directory.
func defaultOpencodePluginPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return opencodePluginPath(home), nil
}

// opencodeInstalled reports whether OpenCode looks present on this machine —
// binary on PATH or ~/.config/opencode exists.
func opencodeInstalled(home string) bool {
	if _, err := exec.LookPath("opencode"); err == nil {
		return true
	}
	info, err := os.Stat(filepath.Join(home, ".config", "opencode"))
	return err == nil && info.IsDir()
}

// currentAuxlyPath resolves the absolute path to the currently running auxly binary.
func currentAuxlyPath() string {
	exe, err := os.Executable()
	if err != nil || exe == "" {
		return "auxly"
	}
	if resolved, err := filepath.EvalSymlinks(exe); err == nil && resolved != "" {
		return resolved
	}
	return exe
}

// generateOpencodePlugin renders the JS plugin template with the given auxly binary path.
func generateOpencodePlugin(auxlyPath string) (string, error) {
	tmpl, err := template.New("opencode").Parse(opencodePluginTemplate)
	if err != nil {
		return "", err
	}
	quoted, err := json.Marshal(auxlyPath)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	data := struct {
		AuxlyPath string
	}{
		AuxlyPath: string(quoted),
	}
	if err := tmpl.Execute(&buf, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// opencodeHookInstalled checks whether the plugin file exists at path.
func opencodeHookInstalled(path string) (bool, error) {
	_, err := os.Stat(path)
	if err == nil {
		return true, nil
	}
	if os.IsNotExist(err) {
		return false, nil
	}
	return false, err
}

// opencodeHookStatus reports WIRED, not-installed, or manual.
func opencodeHookStatus(home string) (status, detail string) {
	path := opencodePluginPath(home)
	if installed, err := opencodeHookInstalled(path); err != nil {
		return "manual", err.Error()
	} else if installed {
		return "WIRED", path
	}
	return "not-installed", "run `auxly hooks install --agent opencode`"
}

// installOpencodeHookAtWithExe writes the capture plugin with the specified auxly binary path.
// Idempotent: rewrites only if content differs.
func installOpencodeHookAtWithExe(path, auxlyPath string) (changed bool, err error) {
	content, err := generateOpencodePlugin(auxlyPath)
	if err != nil {
		return false, err
	}
	existing, err := os.ReadFile(path)
	if err == nil && string(existing) == content {
		return false, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return false, err
	}
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		return false, err
	}
	return true, nil
}

// installOpencodeHookAt writes the capture plugin using currentAuxlyPath.
func installOpencodeHookAt(path string) (changed bool, err error) {
	return installOpencodeHookAtWithExe(path, currentAuxlyPath())
}

// uninstallOpencodeHookAt removes only the plugin file at path, never touching other files.
func uninstallOpencodeHookAt(path string) (removed bool, err error) {
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, err
	}
	if err := os.Remove(path); err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

func installOpencodeHook() error {
	path, err := defaultOpencodePluginPath()
	if err != nil {
		return err
	}
	changed, err := installOpencodeHookAt(path)
	if err != nil {
		return err
	}
	if changed {
		fmt.Println("✅ OpenCode capture plugin installed — facts from each session flow into `auxly pending`.")
		fmt.Printf("   Wrote %s\n", path)
	} else {
		fmt.Println("✓ OpenCode capture plugin already installed — nothing to do.")
	}
	return nil
}

func uninstallOpencodeHook() error {
	path, err := defaultOpencodePluginPath()
	if err != nil {
		return err
	}
	removed, err := uninstallOpencodeHookAt(path)
	if err != nil {
		return err
	}
	if removed {
		fmt.Println("🗑️  OpenCode capture plugin removed.")
	} else {
		fmt.Println("✓ No OpenCode capture plugin found — nothing to remove.")
	}
	return nil
}
